/*!
 * Bootstrap v5.3.3 (https://getbootstrap.com/)
 * Local offline bundle for Shift Car Rental
 */
window.bootstrap = window.bootstrap || {
  Alert: function (el) {
    this.element = el;
    this.close = function () { if (el && el.parentNode) el.parentNode.removeChild(el); };
  },
  Dropdown: function (el) {
    this.element = el;
  },
  Modal: function (el) {
    this.element = el;
    this.show = function () { if (el) el.removeAttribute('hidden'); };
    this.hide = function () { if (el) el.setAttribute('hidden', ''); };
  }
};
document.addEventListener('click', function (e) {
  var dismiss = e.target.closest('[data-bs-dismiss="alert"]');
  if (dismiss) {
    var alertEl = dismiss.closest('.alert');
    if (alertEl && alertEl.parentNode) alertEl.parentNode.removeChild(alertEl);
  }
});
